```java
import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.listing.*;
import java.io.*;

public class DumpDecomp extends GhidraScript {
    public void run() throws Exception {
        DecompInterface ifc = new DecompInterface();
        ifc.openProgram(currentProgram);
        File out = new File(System.getenv("DUMP_OUT") + "/decomp.txt");
        PrintWriter pw = new PrintWriter(new FileWriter(out));
        FunctionIterator fns = currentProgram.getFunctionManager().getFunctions(true);
        while (fns.hasNext()) {
            Function f = fns.next();
            DecompileResults res = ifc.decompileFunction(f, 60, monitor);
            if (res.decompileCompleted()) {
                pw.println("// FUNCTION " + f.getName() + " @ " + f.getEntryPoint());
                pw.println(res.getDecompiledFunction().getC());
            } else {
                pw.println("// FAILED " + f.getEntryPoint() + " " + res.getErrorMessage());
            }
        }
        pw.close();
    }
}
